import{_ as l,c as t,o as s,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"易附錄纂注卷十三","description":"易附錄纂注 - 易附錄纂注卷十三","frontmatter":{"title":"易附錄纂注卷十三","description":"易附錄纂注 - 易附錄纂注卷十三"},"headers":[],"relativePath":"classics/yifulu-zuanzhu/014.md","filePath":"classics/yifulu-zuanzhu/014.md"}'),r={name:"classics/yifulu-zuanzhu/014.md"};function u(i,a,c,o,p,d){return s(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附錄纂注卷十三",tabindex:"-1"},[n("易附錄纂注卷十三 "),e("a",{class:"header-anchor",href:"#易附錄纂注卷十三","aria-label":"Permalink to “易附錄纂注卷十三”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"元胡一桂撰",-1),e("p",null,"愚按：五贊大要皆教人以象佔之學。首篇原奇偶之象，推象之由也。次篇述作者之旨，為佔而作也。三篇明筮以發其佔。四篇稽類以考其象。五篇以警學名。欲人讀易之際，常如卜筮之臨，假象辭以為儀則，而終趨於吉。是又會象佔而一之也。先生嘗曰：「某解易只作卜筮之書，今五贊皆以象佔示教，其旨深矣。」 太一肇判，陰降陽升。陽一以施，陰兩而承。惟皇昊羲，仰觀俯察。奇偶既陳，兩儀斯設。既幹乃支，一各生兩。陰陽交錯，以立四象。奇加以奇，曰陽之陽。奇而加偶，陽陰以章。偶而加奇，陰內陽外。偶復加偶，陰與陰會。兩一既分，一復生兩。三才在目，八卦指掌。奇奇而奇，初一曰乾。奇奇而偶，兌次二焉。奇偶而奇，次三曰離。奇偶而偶，四震以隨。偶奇而奇，巽居次五。偶奇而偶，坎六斯睹；偶偶而奇，艮居次七。偶偶而偶，坤八以畢。初畫為儀，中畫為象，上畫卦成人文斯朗。因而重之。一貞八悔。六十四卦由內達外。附錄。 「貞悔」出洪範。貞是正底，便是體；悔是過底，動則有悔。凡悔，都是過了方悔。這悔是過底意思，亦是多底意思。下三爻便是正卦，上三爻似是過多了。亦似今占卜分甚主客。賀孫。貞是事之始，悔是事之終；貞是事之主，悔是事之客；貞是在我底，悔是應人底。「一貞八悔」，如乾至泰，內體皆乾，是一貞；外體八卦，是八悔。餘放此。義剛。 交易為體，往此來彼。附錄。 先天圖一邊本都是陽，一邊本都是陰。陽中有陰，陰中有陽，便是陽往交易陰，陰來交易陽，兩邊各各相對。其實非此往彼來，只其象如此。僩。 「變易為用」，時靜時動。降帝而王，傳夏曆商。「有佔無文，民用弗章。」文王系彖，周公系爻，視此八卦，二純六交。乃乾斯父，乃坤斯母。震坎艮男，巽離兌女，離南坎北，震東兌西，乾坤艮巽，位以四維。建官立師，命曰周易。孔聖傳之，是為十翼。遭秦弗燼，及宋而明，邵傳羲畫，程演周經。象陳數列，言盡理得，彌億萬年，永著常式。",-1),e("p",null,"昔在上古，世質民淳，是非莫別，利害不分。風氣既開，乃生聖人，聰明睿知，出類超群。仰觀俯察，始畫奇偶，教之卜筮，以斷可否。作為君飾，開鑿戶牖，民用不迷，以有常守。降及中古，世變風移，淳澆質喪，民偽日滋。穆穆文王，身蒙大難，安土樂天，惟世之患。乃本卦義，系此彖辭。爰及周公，六爻是資。因事設教，丁寧詳密，必中必正，乃亨乃吉。語子惟孝，語臣則忠，鉤深闡微，如日之中。爰暨末流，淫於術數，僂句成欺，黃裳亦誤。纂注 左傳昭公二十五年：臧昭伯如晉，臧會竊其寶龜僂句以卜，為信與僭，僭吉。後平子立會，會曰：「僂句不餘欺也。」注：僂句，龜所出地名。僭，不信也，謂求立為臧氏後也。黃裳事見坤卦六五爻。 大哉孔子，晚好是書，韋編既絕，八索以祛。乃作彖、象，十翼之篇，專用義理，發揮經言。居省象辭，動察變佔，存亡進退，陟降飛潛，曰毫曰釐，匪差匪繆，假我數年，庶無大咎。恭惟三古，四聖一心，垂象炳明，千載是臨。惟是學者，不本其初，文辭象數，或肆或拘。嗟予小子，既微且陋，鑽仰沒身，奚測奚究。匪警滋荒，匪識滋漏，維用存疑，敢曰垂後。",-1),e("p",null,"倚數之元，參天兩地，衍而極之，五十乃備。是曰大衍，虛一無為。其為用者，四十九蓍。信手平分，置右於幾。取右一蓍，掛左小指。乃以右手，揲左之策。四四之餘，歸之於扐。初扐左手，無名指間，右策左揲，將指是安。再扐之奇，通掛之算，不五則九，是謂一變。置此掛扐，再用存策，分掛揲歸，復準前式。三亦如之，奇皆四八。三變既備，數斯可察。數之可察，其辨伊何。四五為少，八九為多。三少為九，是曰老陽。三多為六，老陰是當。一少兩多，少陽之七。孰八少陰，少兩多一。既得初爻，複合前蓍。四十有九，如前之為。三變一爻，通十八變。六爻發揮，卦體可見。老極而變，少守其常。六爻皆守，彖辭是當。變視其爻，兩兼首尾。變及三爻，佔兩卦體。或四或五，視彼所存。四二五一，二分一專。皆變而他，新成舊毀。消息盈虛，舍此視彼。乾佔用九，坤佔用六。「泰」愕匪人，姤喜來複。",-1),e("p",null,"八卦之象，說卦詳焉。考之於經，其用弗專。彖以情言，象以象告。惟是之求，斯得其要。乾健天行，坤順地從。震動為雷，巽入木風。坎險水泉，亦云亦雨。離麗文明，電日而火。艮止為山，兌說為澤。以是舉之，其要斯得。凡卦六虛，奇偶殊位。奇陽偶陰，各以其類。得位為正，二五為中，二臣五君，初始上終。貞悔體分，爻以位應。陰陽相求，乃得其正。凡陽斯淑，君子居之。凡陰斯慝，小人是為。常可類求，變非例測。非常曷變？謹此為則。",-1),e("p",null,"讀易之法，先正其心。肅容端席，有翼其臨。於卦於爻，如筮斯得。假彼象辭，為我儀則。字從其訓，句逆其情，事因其理，意適其平。曰否曰臧，如目斯見，曰止曰行，如足斯踐。毋寬以略，毋密以窮，毋固而可，毋必而通。平易從容，自表而裡。及其貫之，萬事一理。理定既實，事來尚虛。用應始有，體該本無。稽實待虛，存體應用。執古御今，由靜制動。附錄：聖人作易，只說一個理，都未曾有許多事，卻待甚麼事來湊？所謂「事來尚虛」，蓋謂事之方來，尚虛而未有。若論其理，則先自定，固已實矣。「用應始有」，謂理之用實，故有。「體該本無」，謂理之體該萬物，初無形跡可見，故無。下雲「稽考實理，以待事物之來」，存此理之體，以應無窮之用。「執古」，古便是易書裡面言語。「御今」，今便是今日之事。「以靜制動」，理便是靜底，事便是動底。敬之 潔靜精微，是之謂易。體之在我，動有常吉。在昔程氏，繼周紹孔，奧指宏剛，星陳極拱。惟斯未啟，以俟後人，小子狂簡，敢述而申。易附錄纂注卷十三。",-1)])])}const _=l(r,[["render",u]]);export{m as __pageData,_ as default};
